import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

type Row = {
  id: string; status: string; input: string; steps: number; fail_attempts: number;
  attempts: number; progress_completed: number; result_output: string | null;
  error: string | null; created_at: string; updated_at: string;
};

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: {field: string; message: string}[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
function toJob(row: Row) {
  return {
    id: row.id, status: row.status, input: row.input, steps: row.steps,
    failAttempts: row.fail_attempts, attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at, updatedAt: row.updated_at,
  };
}
function getJob(id: string) {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as Row | undefined;
}
function invalid(res: ServerResponse, fields: {field: string; message: string}[]): void {
  error(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const data = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    size += data.length;
    if (size > 1024 * 1024) throw new Error('body too large');
    chunks.push(data);
  }
  return Buffer.concat(chunks).toString('utf8');
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: {field: string; message: string}[] = [];
  const contentType = req.headers['content-type'];
  if (!contentType || !/^application\/json(?:\s*;|\s*$)/i.test(contentType)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  }
  const idem = req.headers['idempotency-key'];
  if (idem !== undefined && (Array.isArray(idem) || !/^[A-Za-z0-9_-]{1,128}$/.test(idem))) {
    fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, digits, underscores, or hyphens.' });
  }
  let body: unknown;
  try { body = JSON.parse(await readBody(req)); }
  catch { fields.push({ field: 'body', message: 'Must be valid JSON.' }); }
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    fields.push({ field: 'body', message: 'Must be a JSON object.' });
  }
  if (fields.length) return invalid(res, fields);
  const obj = body as Record<string, unknown>;
  for (const key of Object.keys(obj)) {
    if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
  }
  if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
  else {
    if (obj.input.length < 1 || obj.input.length > 1000) fields.push({ field: 'input', message: 'Must be between 1 and 1000 characters.' });
    if (!obj.input.trim()) fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  }
  const steps = obj.steps === undefined ? 5 : obj.steps;
  const failAttempts = obj.failAttempts === undefined ? 0 : obj.failAttempts;
  if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20)
    fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5)
    fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
  if (fields.length) return invalid(res, fields);

  const payload = JSON.stringify({ input: obj.input, steps, failAttempts });
  const key = idem as string | undefined;
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key) {
      const previous = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(key) as {payload: string; job_id: string} | undefined;
      if (previous) {
        db.exec('COMMIT');
        if (previous.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        const row = getJob(previous.job_id);
        if (row) return send(res, 200, toJob(row));
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at)
      VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?)`).run(id, obj.input as string, steps as number, failAttempts as number, now, now);
    if (key) db.prepare('INSERT INTO idempotency (key,payload,job_id) VALUES (?,?,?)').run(key, payload, id);
    db.exec('COMMIT');
    const row = getJob(id)!;
    send(res, 201, toJob(row));
  } catch (e) {
    try { db.exec('ROLLBACK'); } catch { /* transaction already ended */ }
    throw e;
  }
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const beat = db.prepare('SELECT heartbeat FROM worker_state WHERE singleton = 1').get() as {heartbeat: number} | undefined;
    return send(res, 200, { status: 'ok', worker: beat && Date.now() - beat.heartbeat <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'POST') {
      try { await createJob(req, res); }
      catch { if (!res.headersSent) error(res, 400, 'invalid_request', 'The request could not be read.', [{ field: 'body', message: 'Could not read request body.' }]); }
      return;
    }
    if (req.method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as unknown as Row[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string;
    try { id = decodeURIComponent(match[1]!); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const row = getJob(id);
    return row ? send(res, 200, toJob(row)) : error(res, 404, 'not_found', 'Job not found.');
  }
  error(res, 404, 'not_found', 'Route not found.');
});
server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown() {
  server.close(() => { db.close(); process.exit(0); });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

