import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
const nowIso = () => new Date().toISOString();
function heartbeat(): void {
  db.prepare(`INSERT INTO worker_state(singleton, heartbeat) VALUES (1, ?)
    ON CONFLICT(singleton) DO UPDATE SET heartbeat=excluded.heartbeat`).run(Date.now());
}

// A running row belongs to a worker that did not finish. Requeue it so a restart resumes safely.
db.prepare(`UPDATE jobs SET status='queued', progress_completed=0, retry_at=0, updated_at=? WHERE status='running'`).run(nowIso());
heartbeat();
const heartbeatTimer = setInterval(() => {
  try { heartbeat(); } catch (e) { console.error('worker heartbeat failed', e); }
}, 500);
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

type WorkRow = { id: string; input: string; steps: number; fail_attempts: number; attempts: number };
function claim(): WorkRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare(`SELECT id,input,steps,fail_attempts,attempts FROM jobs
      WHERE status='queued' AND retry_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(Date.now()) as WorkRow | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const result = db.prepare(`UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=?
      WHERE id=? AND status='queued'`).run(nowIso(), row.id);
    db.exec('COMMIT');
    if (Number(result.changes) !== 1) return undefined;
    return { ...row, attempts: row.attempts + 1 };
  } catch (e) {
    try { db.exec('ROLLBACK'); } catch { /* already ended */ }
    throw e;
  }
}

async function processJob(job: WorkRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    await sleep(100);
    if (stopping) return;
    const now = nowIso();
    if (job.attempts >= 3) {
      db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result_output=NULL,
        updated_at=?, progress_completed=0 WHERE id=? AND status='running'`).run(now, job.id);
    } else {
      db.prepare(`UPDATE jobs SET status='queued', error=NULL, result_output=NULL, retry_at=?, updated_at=?
        WHERE id=? AND status='running'`).run(Date.now() + 300, now, job.id);
    }
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(100);
    if (stopping) return;
    db.prepare(`UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'`)
      .run(step, nowIso(), job.id);
  }
  db.prepare(`UPDATE jobs SET status='completed', result_output=?, error=NULL, retry_at=0, updated_at=?
    WHERE id=? AND status='running'`).run(job.input.toUpperCase(), nowIso(), job.id);
}

console.log('worker started');
try {
  while (!stopping) {
    heartbeat();
    const job = claim();
    if (!job) { await sleep(100); continue; }
    await processJob(job);
  }
} finally {
  clearInterval(heartbeatTimer);
  db.close();
}

